/* Generated by `helix family machines` from machine.ts beside it. Do not
   edit: change the machine and run it again. */
import { type ToggleContext, changeable, flip, isChecked, isMixed, resolvesOn } from './machine.js'

export type { ToggleContext } from './machine.js'

/** The name machine.ts exports the machine as. */
export const NAME = 'toggle'

/** The state `mixed`. */
export const STATE_MIXED = 0
/** The state `off`. */
export const STATE_OFF = 1
/** The state `on`. */
export const STATE_ON = 2
/** Each state's name, by its number. */
export const STATES = ['mixed', 'off', 'on'] as const

/** Each state as the machine writes it, by the number a deadline names its owner by. */
export const NODES = ['mixed', 'off', 'on'] as const

/** The event `PRESS`. */
export const EVENT_PRESS = 0
/** Each event's name, by its number. */
export const EVENTS = ['PRESS'] as const

/** The effect `announce`. */
export const EFFECT_ANNOUNCE = 0
/** The effect `report`. */
export const EFFECT_REPORT = 1
/** Each effect's name, by its number. */
export const EFFECTS = ['announce', 'report'] as const

/** The request event `toggle`. */
export const ASK_TOGGLE = 0
/** Each request event's name, by its number. */
export const ASKS = ['toggle'] as const

/** A literal an effect is given. */
export type Argument = Readonly<Record<string, boolean | number | string>>

/** An effect the host performs: its number, and its argument where it has one. */
export type Effect = readonly [effect: number, argument?: Argument]

/** A move: the state it leaves the machine in, the context after it, and the effects it runs, in order. */
export interface Move {
  readonly context: ToggleContext
  readonly effects: readonly Effect[]
  readonly state: number
}

/** A request: the events the host asks with first, in order, and the move for each outcome. */
export interface Asking {
  readonly accept: Move
  readonly ask: readonly number[]
  readonly refuse: Move
}

/** The state the machine is in, read from its context. */
export const start = (context: ToggleContext): number =>
  isMixed(context) ? STATE_MIXED : isChecked(context) ? STATE_ON : STATE_OFF

/** The effects of starting in a state, as a host that mounts the machine runs them. */
export const entering = (state: number): readonly Effect[] => {
  switch (state) {
    case STATE_MIXED:
      return [[EFFECT_REPORT]]
    case STATE_OFF:
      return [[EFFECT_REPORT]]
    case STATE_ON:
      return [[EFFECT_REPORT]]
  }
  return []
}

/** What `mixed` does with each event. */
const inMixed = (context: ToggleContext, event: number, _input: undefined): Move | Asking | undefined => {
  switch (event) {
    case EVENT_PRESS:
      return resolvesOn(context) ? { accept: { context: flip(context), effects: [[EFFECT_ANNOUNCE], [EFFECT_REPORT]], state: STATE_ON }, ask: [ASK_TOGGLE], refuse: { context: context, effects: [], state: STATE_MIXED } } : changeable(context) ? { accept: { context: flip(context), effects: [[EFFECT_ANNOUNCE], [EFFECT_REPORT]], state: STATE_OFF }, ask: [ASK_TOGGLE], refuse: { context: context, effects: [], state: STATE_MIXED } } : undefined
  }
  return undefined
}

/** What `off` does with each event. */
const inOff = (context: ToggleContext, event: number, _input: undefined): Move | Asking | undefined => {
  switch (event) {
    case EVENT_PRESS:
      return changeable(context) ? { accept: { context: flip(context), effects: [[EFFECT_ANNOUNCE], [EFFECT_REPORT]], state: STATE_ON }, ask: [ASK_TOGGLE], refuse: { context: context, effects: [], state: STATE_OFF } } : undefined
  }
  return undefined
}

/** What `on` does with each event. */
const inOn = (context: ToggleContext, event: number, _input: undefined): Move | Asking | undefined => {
  switch (event) {
    case EVENT_PRESS:
      return changeable(context) ? { accept: { context: flip(context), effects: [[EFFECT_ANNOUNCE], [EFFECT_REPORT]], state: STATE_OFF }, ask: [ASK_TOGGLE], refuse: { context: context, effects: [], state: STATE_ON } } : undefined
  }
  return undefined
}

/**
 * What an event does in a state: a move, a request, or `undefined` where the
 * state ignores it.
 */
export const step = (state: number, context: ToggleContext, event: number, input: undefined): Move | Asking | undefined => {
  switch (state) {
    case STATE_MIXED:
      return inMixed(context, event, input)
    case STATE_OFF:
      return inOff(context, event, input)
    case STATE_ON:
      return inOn(context, event, input)
  }
  return undefined
}

/**
 * The move a state's deadline makes when it ends, or `undefined` where the
 * state `owner` names is not active in `state`.
 */
export const expire = (_state: number, _context: ToggleContext, _owner: number): Move | undefined =>
  undefined

/** The move the machine's cancel makes from a state, where it has one. */
export const cancel = (_state: number, _context: ToggleContext): Move | undefined => undefined

/** The custom states a host records while the machine is in `state`. */
export const mark = (_state: number): readonly string[] => []
